class Solution { public: int numberOfSpecialChars(string word) {
 vector<int> last(26,-1),first(26,INT_MAX); for(int i=0;i<(int)word.size();++i){char c=word[i];if(islower(c))last[c-'a']=i;else first[c-'A']=min(first[c-'A'],i);}int ans=0;for(int i=0;i<26;++i)ans+=last[i]>=0&&first[i]!=INT_MAX&&last[i]<first[i];return ans;
}};
